import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates by mean difference and t-statistic
    candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'expression':
            # Simplified t-statistic calculation
            mean_diff = np.mean(feats.x[feats.y==1, feats.column(fid)]) - np.mean(feats.x[feats.y==0, feats.column(fid)])
            std_diff = np.std(feats.x[:, feats.column(fid)]) * np.sqrt(feats.n)
            t_stat = mean_diff / std_diff if std_diff != 0 else 0
            if abs(mean_diff) > 0.3 and abs(t_stat) > 3:
                candidates.append((fid, abs(mean_diff), abs(t_stat)))

    # Sort by strength
    candidates.sort(key=lambda x: x[2], reverse=True)

    # Cluster correlated features based on correlation matrix
    corr_matrix = np.corrcoef(feats.x.T)
    high_corr_pairs = []
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if abs(corr_matrix[i,j]) >= 0.6:
                high_corr_pairs.append((feats.ids[i], feats.ids[j]))

    # Build clusters of highly correlated features
    all_features = list(feats.ids)
    clusters = []
    used = set()

    for fid1, fid2 in high_corr_pairs:
        if fid1 in used or fid2 in used:
            continue
        cluster = {fid1, fid2}
        used.add(fid1)
        used.add(fid2)

        # Expand cluster
        for fid3, fid4 in high_corr_pairs:
            if fid3 in cluster or fid4 in cluster:
                cluster.add(fid3)
                cluster.add(fid4)
                used.add(fid3)
                used.add(fid4)

        clusters.append(list(cluster))

    # For each cluster, select the most significant feature
    drivers = []
    for cluster in clusters:
        cluster_features = [(fid, next(c for c in candidates if c[0]==fid)) for fid in cluster if any(c[0]==fid for c in candidates)]
        if cluster_features:
            best_fid = max(cluster_features, key=lambda x: x[1][2])[0]
            drivers.append(best_fid)

    # Add top non-correlated candidates
    for fid, _, _ in candidates[:5]:
        if fid not in drivers and not any(fid in c for c in clusters):
            drivers.append(fid)
            if len(drivers) >= MAX_DRIVERS:
                break

    # Remove near-duplicates
    final_drivers = []
    used_features = set()
    for fid in drivers:
        is_duplicate = False
        for used_fid in used_features:
            if abs(corr_matrix[feats.column(fid), feats.column(used_fid)]) > 0.9:
                is_duplicate = True
                break
        if not is_duplicate:
            used_features.add(fid)
            final_drivers.append(fid)

    # Select columns for regression (top features)
    columns = [fid for fid, _, _ in candidates[:10]]

    # Check for interactions between top features
    products = []
    for i, fid1 in enumerate(columns):
        for fid2 in columns[i+1:]:
            if abs(corr_matrix[feats.column(fid1), feats.column(fid2)]) > 0.5:
                products.append((fid1, fid2))

    # Loadings for weighted score
    loadings = {}
    for fid in columns:
        loadings[fid] = np.abs(np.mean(feats.x[feats.y==1, feats.column(fid)]) - 
                              np.mean(feats.x[feats.y==0, feats.column(fid)]))

    return Design(
        drivers=tuple(final_drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

